from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            j = i
            while j < len(paren_string) and paren_string[j] != ')':
                j += 1
            if j < len(paren_string) and paren_string[j] == ')':
                groups.append(paren_string[i:j+1])
                i = j + 1
            else:
                # Invalid input, but problem states input is valid
                pass
        else:
            i += 1
    return groups

