    def get_sign_digits(num):
        if num == 0:
            return [0]
        digits = []
        sign = 1
        if num < 0:
            sign = -1
            num = -num
        while num > 0:
            digits.append(num % 10)
            num //= 10
        return [sign * d for d in digits]

    count = 0
    for num in arr:
        digits = get_sign_digits(num)
        if sum(digits) > 0:
            count += 1
    return count

