def words_in_sentence(sentence):
    import math
    primes = set()
    for i in range(2, int(math.isqrt(100)) + 1):
        if i * i > 100:
            break
        for j in range(i, 100, i):
            primes.add(j)
    result = []
    words = sentence.split()
    for word in words:
        if len(word) in primes:
            result.append(word)
    return ' '.join(result)

