def sort_third(l: list):
    # Extract the elements at indices divisible by 3
    sorted_values = sorted(l[i] for i in range(len(l)) if i % 3 == 0)

    # Create a new list where elements at indices divisible by 3 are the sorted values
    result = []
    index = 0
    while index < len(l):
        if index % 3 == 0:
            result.append(sorted_values.pop(0))
        else:
            result.append(l[index])
        index += 1

    return result

